/**
 * SVA example: Magic Circle Toggle
 * Draws a spell-school magic circle under each selected token. The circle keeps looping (and is
 * saved in the scene) until you run the macro again; it then plays its closing animation.
 *
 * Usage: select tokens, run. Change SCHOOL and COLOR below.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

// abjuration, conjuration, divination, enchantment, evocation, illusion, necromancy, transmutation
const SCHOOL = "evocation";
// blue, green, pink, purple, red, yellow, or dark_ + one of those (dark_red, dark_blue...)
const COLOR = "red";
const SCALE = 2;

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;
const file = `jb2a.magic_signs.circle.02.${SCHOOL}.complete.${COLOR}`;
if (!SVA.db.has(file)) return ui.notifications.warn(`No JB2A animation at ${file}.`);

for (const tok of tokens) {
  const name = `sva-magic-circle:${tok.id}`;
  if (SVA.effects.list({ sceneId, name }).length) {
    // The "complete" file has intro, loop and outro: ending it plays the outro.
    await SVA.effects.end({ name, sceneId });
    continue;
  }
  const seq = SVA.sequence();
  seq.effect().file(file).attachTo(tok.id).scaleToObject(SCALE).layer("belowTokens").persist(true).name(name);
  await seq.play();
}
